<script setup lang="ts">
import {computed} from 'vue'
import {qualityGroups,latestServices,downloadEvidence,attemptObservedAt,latencyReadComplete,type QualityEvidence} from '../nodeQuality'
import {date,downloadSpeed,outcomeLabel,type ServiceRule} from '../domain'
import {downloadGroup} from '../sharedResults'
import {attemptStatus,downloadConditionLabel} from '../measurementRounds'
const props=defineProps<{evidence?:QualityEvidence;target:string;error?:string;catalog:ServiceRule[];expanded?:boolean;comparisonField?:'distribution'|'response'|'download'|'service'|'time'|'details'}>()
const groups=computed(()=>props.evidence?qualityGroups(props.evidence.tests,props.evidence.monitor,props.target):[])
const current=computed(()=>groups.value[0]),downloads=computed(()=>downloadEvidence(props.evidence?.downloads||[]))
const download=computed(()=>downloads.value.latest),validDownload=computed(()=>downloads.value.valid),speed=computed(()=>downloadSpeed(validDownload.value))
const services=computed(()=>latestServices(props.evidence?.services||[]))
const downloadTitle=computed(()=>[download.value?'最近检测：'+downloadConditionLabel(download.value):'',validDownload.value?'最近有效：'+downloadGroup(validDownload.value).label:''].filter(Boolean).join('\n'))
const readNames:Record<string,string>={latency:'延迟',monitor:'旧监测',download:'下载',service:'服务'}
const ms=(v:number|null|undefined)=>v===null||v===undefined?'—':Math.round(v)+' ms'
const title=computed(()=>current.value?`${current.value.source} · ${current.value.method} · ${current.value.target}\n条件：${current.value.condition}`:'无已保存样本')
</script>
<template><div class="quality-metrics" :class="{expanded,'comparison-field':comparisonField}"><template v-if="comparisonField&&(!evidence||error)"><strong class="muted">{{error?'读取失败 · 不可比较':'读取保存记录…'}}</strong><small v-if="error">{{error}}</small></template><template v-else>
 <section v-if="!comparisonField||comparisonField==='distribution'||comparisonField==='response'" class="quality-latency" :title="title"><template v-if="error"><strong class="bad">读取失败</strong><small>{{error}}</small></template><template v-else-if="!evidence"><strong class="muted">读取保存记录…</strong></template><template v-else-if="!current||!current.total"><strong class="muted">未测</strong><small>{{current?.excluded?'仅取消 / 条件不足记录，未计失败':'所选站点无历史样本'}}</small></template><template v-else><div v-if="!comparisonField||comparisonField==='distribution'"><strong>P50 {{ms(current.p50)}}</strong><span class="quality-secondary">P95 {{current.success<20?'样本不足':ms(current.p95)}}</span></div><div v-if="!comparisonField||comparisonField==='response'"><span>响应成功 {{current.successRate===null?'—':current.successRate.toFixed(0)+'%'}}</span><span class="quality-secondary">{{current.success}} / {{current.total}} 样本</span><span v-if="current.insufficient" class="warn">样本不足</span></div><small v-if="!comparisonField">{{date(current.lastAt)}} · {{current.source==='monitor'?'旧监测 RTT':current.method==='http_get_via_proxy_first_byte'?'HTTP 首字节':'方法 '+current.method}}<span v-if="groups.length>1"> · {{groups.length}} 条件组（显示最新组）</span></small><small v-if="current.insufficient||!current.comparable" class="warn">不可比较 · {{current.insufficient?'样本不足':''}}{{current.insufficient&&!current.comparable?'；':''}}{{!current.comparable?'方法或出口条件证据不足':''}}</small></template><small v-if="evidence&&current&&!latencyReadComplete(evidence,current)" class="warn">{{current.source==='monitor'?'旧监测':'延迟'}}读取不完整 · 不可比较</small><small v-if="evidence&&!current&&(!evidence.reads.latency.complete||!evidence.reads.monitor.complete)" class="warn">延迟/旧监测读取不完整 · 未测状态未确认</small></section>
 <section v-if="!comparisonField||comparisonField==='download'" class="quality-download" :title="downloadTitle"><strong>最近检测：{{download?attemptStatus(download,true):'未测'}}</strong><small v-if="download">{{date(attemptObservedAt(download))}} · {{download.rule.method||'方法未知'}} / v{{download.rule.rule_version??'?'}}</small><small v-if="validDownload">{{validDownload.attempt_id===download?.attempt_id?'最近有效速度':'历史有效速度'}}：{{speed!.toFixed(2)}} MiB/s · {{downloadGroup(validDownload).kind==='partial'?'有效部分':'完整读取'}} · {{date(attemptObservedAt(validDownload))}}</small><small v-else>无有效速度 · 下载条件独立比较</small><small v-if="evidence&&!evidence.reads.download.complete" class="warn">下载读取不完整 · 最近状态/速度未确认{{comparisonField?' · 不可比较':''}}</small><small v-if="comparisonField&&download" class="comparison-condition">最近检测条件：{{downloadConditionLabel(download)}}</small><small v-if="comparisonField&&validDownload" class="comparison-condition">{{validDownload.attempt_id===download?.attempt_id?'速度条件':'历史速度条件'}}：{{downloadGroup(validDownload).label}}</small></section>
 <section v-if="!comparisonField||comparisonField==='service'" class="quality-services"><strong>服务 {{services.length?'最近有记录 '+services.length+' 项':'未测'}}</strong><small v-for="a in services.slice(0,expanded||comparisonField==='service'?services.length:2)" :key="a.service_id||a.rule.service_id">{{catalog.find(s=>s.service_id===(a.service_id||a.rule.service_id))?.name||a.service_id||a.rule.service_id}}：{{a.result?.outcome==='not_executed'?'未执行':a.result?outcomeLabel(a.result.outcome):attemptStatus(a)}} · {{date(attemptObservedAt(a))}}</small><small v-if="evidence&&!evidence.reads.service.complete" class="warn">服务读取不完整 · 最近结论未确认{{comparisonField?' · 不可比较':''}}</small></section>
 <section v-if="comparisonField==='time'" class="quality-times"><small>延迟：<time v-if="current" :datetime="current.lastAt">{{date(current.lastAt)}}</time><span v-else>未测</span></small><small>下载：<time v-if="download" :datetime="attemptObservedAt(download)">{{date(attemptObservedAt(download))}}</time><span v-else>未测</span></small><small v-if="validDownload&&validDownload.attempt_id!==download?.attempt_id">历史有效：<time :datetime="attemptObservedAt(validDownload)">{{date(attemptObservedAt(validDownload))}}</time></small><small v-for="a in services" :key="a.service_id||a.rule.service_id">{{catalog.find(s=>s.service_id===(a.service_id||a.rule.service_id))?.name||a.service_id||a.rule.service_id}}：<time :datetime="attemptObservedAt(a)">{{date(attemptObservedAt(a))}}</time></small><small v-if="!services.length">服务：未测</small></section>
 <details v-if="(expanded||comparisonField==='details')&&(!comparisonField||comparisonField==='details')&&evidence" class="quality-evidence-details"><summary>分组依据、样本与边界</summary><p>固定窗口 {{date(evidence.since)}} — {{date(evidence.until)}}；{{evidence.complete?'已读完窗口内保存记录':'读取不完整'}}。响应成功率不代表业务可用。P95 至少 20 个成功样本才在列表展示；5 个以下成功样本标为样本不足。波动为成功时延的总体标准差。</p><p v-for="(status,kind) in evidence.reads" :key="kind">{{readNames[kind]}}历史：{{status.complete?'读取完整':'读取不完整'}}{{status.error?' · '+status.error:''}}</p><article v-for="g in groups" :key="g.key"><strong>{{g.source}} · {{g.method}}</strong><p>{{g.target}} · {{g.success}}/{{g.total}} · P50 {{ms(g.p50)}} · P95 描述值 {{ms(g.p95)}} · 波动 {{ms(g.jitter)}} · 排除取消/未执行 {{g.excluded}}</p><p>{{g.comparable?'方法与路径有记录；仅同条件组可比较':'不可比较：旧方法或路径条件缺失'}} · {{g.condition}}</p></article><p v-if="download">最近检测条件：{{downloadConditionLabel(download)}}</p><p v-if="validDownload">最近有效速度条件：{{downloadGroup(validDownload).label}}</p><p>没有综合评分；不同目标、来源、协议、方法、版本和出口条件不合并。节点地区取自名称/配置，不等于出口地区。</p></details>
</template></div></template>
